from pathlib import Path
import shutil
D=Path('work/kizomba-site/dist')
shutil.copy('work/residencia-land.png',D/'residencia-120.png')
for n in ['103','202','501','502','700','800']:shutil.copy(f'work/salao/{n}-1.png',D/f'salao-{n}.png')
(D/'document-data.js').write_text("const salonDocuments="+str([dict(id=n,title=t,image=f'salao-{n}.png') for n,t in [('103','Incêndio e protecção portátil'),('202','CFTV'),('501','Rede de incêndio / hidrantes'),('502','Sprinklers'),('700','Compartimentação e evacuação'),('800','Extinção na cozinha')]]).replace("'",'"')+";\nlet salonDocument='103';\nconst residenceDocumentImage='residencia-120.png';\n")
p=D/'index.html';s=p.read_text().replace('<script src="app.js">','<script src="document-data.js"></script><script src="app.js">');s=s.replace('<button data-area="Administração">Administração</button>','<button data-area="Administração">Administração</button><button data-area="Salão de festas">Salão de festas</button>',1);p.write_text(s)
p=D/'app.js';s=p.read_text();s=s.replace("if(selected==='Administração')", "if(['Administração','Salão de festas'].includes(selected))",2)
s=s.replace("if(selected==='Administração')$('residenceDetail').hidden=false", "if(['Administração','Salão de festas'].includes(selected))$('residenceDetail').hidden=false")
s=s.replace("if(selected==='Administração')renderAdminPlans(points,opened);", """if(selected==='Administração')renderAdminPlans(points,opened);
else if(selected==='Salão de festas')renderSalonDocuments(points,opened);
else $('equipmentFloors').innerHTML+=`<details class="panel"><summary>Planta SADI T3 · normal e espelhada (2014)</summary><p>Referência documental comum; orientação da casa por confirmar. O desenho indica detectores térmicos na sala/cozinha, óptico na lavandaria e combinados nos quartos; pânico nos dois pisos. O relato actual e esta planta divergem: conferir em campo antes de alterar o cadastro. Os símbolos e cotas não são endereços electrónicos.</p><img style="width:100%" src="${residenceDocumentImage}" alt="Planta de incêndio T3 normal e espelhada"><p>Ligação documental desta casa: ${esc((pointRoute(selected,null)||{}).station||'por identificar')} · Loop ${esc((pointRoute(selected,null)||{}).loop||'por identificar')}. Percurso interno nesta planta; distribuição geral conforme plantas 720 e 113. Sem ligação física implementada.</p></details>`;""")
s=s.replace("function pointRoute(a,p){", "function pointRoute(a,p){if(a==='Salão de festas'){return !p||['Incêndio','Pânico','Alarme técnico','Assistência'].includes(p.system)?{station:'SADI 2',loop:7}:{station:'Central / interface por identificar',loop:null};}")
s=s.replace("const b=e.target.closest('[data-equipment]');const layer=", "const doc=e.target.closest('[data-salon-document]');if(doc){salonDocument=doc.dataset.salonDocument;render();return;}const b=e.target.closest('[data-equipment]');const layer=")
s=s.replace("$('residenceNote').textContent=selected==='Administração'?", "$('residenceNote').textContent=selected==='Salão de festas'?'Zona comum partilhada. Seis desenhos documentais de 2015; cadastro individual ainda por conferir. Incêndio: SADI 2, Loop 7 conforme planta 720.':selected==='Administração'?")
s += '''\nfunction renderSalonDocuments(points,opened){const doc=salonDocuments.find(d=>d.id===salonDocument)||salonDocuments[0];$('equipmentFloors').innerHTML=`<div class="adminPlans"><div class="toolbar">${salonDocuments.map(d=>`<button data-salon-document="${d.id}" class="${d.id===doc.id?'active':''}">${esc(d.title)}</button>`).join('')}</div><p>Planta ${doc.id} · referência documental de 2015. Não representa o estado actual nem uma ligação activa à central.</p><img style="width:100%" src="${doc.image}" alt="Salão de festas: ${esc(doc.title)}"><p>Hidrantes, sprinklers, extinção de cozinha e sinalização são protecções distintas. Apenas interfaces eléctricas identificadas e compatíveis poderão produzir eventos na supervisão. Não há comandos de extinção nesta demonstração.</p></div>`;$('extraEquipment').innerHTML=points.length?'<h3>Equipamentos cadastrados nesta zona comum</h3>'+points.map(p=>pointButton(p,opened)).join(''):'<p class="notice">Cadastro individual pendente: adicionar código, piso, divisão, posição física e endereço verificados em Equipamentos. As ocorrências sem ponto individual identificam apenas a área.</p>';}
'''
p.write_text(s)
